46			t.Fatalf("encoding must be deterministic: equal=%v err=%v", bytes.Equal(again, archive), err)
47		}
48	
49		got, err := DecodeAuditArchive(archive, "acme", cp)
50		if err != nil {
51			t.Fatalf("decode: %v", err)
52		}
53		if !reflect.DeepEqual(got, recs) {
54			t.Fatalf("decoded records differ from export:\n got %+v\nwant %+v", got, recs)
55		}
