42	// legacyJSONFingerprint is the exact fingerprint algorithm used before
43	// the raw-content integrity fix: encoding/json over the envelope. Tests
44	// use it to prove valid-UTF-8 records keep byte-identical fingerprints.
45	func legacyJSONFingerprint(r *AuditRecord) string {
46		b, err := json.Marshal(&hashEnvelope{
47			Org:             r.Org,
48			Seq:             r.Seq,
49			Kind:            r.Kind,
50			Change:          r.Change,
51			Decision:        r.Decision,
52			PrevFingerprint: r.PrevFingerprint,
53		})
54		if err != nil {
55			panic(err)
56		}
57		sum := sha256.Sum256(b)
58		return hex.EncodeToString(sum[:])
59	}
