280		bad = cloneExportedRecords(recs)
281		bad[0].Change.Policies[0].ID = "p2"
282		if err := VerifyAudit("acme", bad, cp); !errors.Is(err, ErrInvalidRange) {
283			t.Fatalf("tampered ordinary record err = %v, want ErrInvalidRange", err)
284		}
285	}
286	
287	// buildInvalidByteChain constructs a chain where every fingerprinted
288	// string field can be probed. Record 1 is a policy change, record 2 the
289	// reviewed decision with an invalid byte embedded between legal Chinese
290	// in every nested field and list, record 3 a decision after the target.
291	func buildInvalidByteChain(t *testing.T) (string, []AuditRecord, Checkpoint) {
292		t.Helper()
293		org := "组" + invalidByte + "织"
294		subjectID := "身" + invalidByte + "份"
295		action := "动" + invalidByte + "作"
296		scope := "范" + invalidByte + "围"
297		p1 := Policy{
298			ID:      "策" + invalidByte + "id",
299			Subject: subjectID,
300			Action:  action,
301			Scope:   scope,
302			Effect:  EffectAllow,
303		}
304		p2 := Policy{
305			ID:      "命" + invalidByte + "中二",
306			Subject: subjectID,
307			Action:  action,
308			Scope:   scope,
309			Effect:  EffectAllow,
310		}
311		prev := genesisFingerprint(org)
312		rec1 := syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
313			Version: 1, Policies: []Policy{p1, p2},
314		}, nil, prev)
315		prev = rec1.Fingerprint
316		rec2 := syntheticRecord(org, 2, AuditDecision, nil, &DecisionRecord{
317			Request: OrgRequest{
318				SubjectOrg:  org,
319				ResourceOrg: org,
320				Subject: Subject{
321					ID:    subjectID, // invalid byte between legal Chinese
322					Kind:  "类" + invalidByte + "型",
323					Roles: []string{"角" + invalidByte + "色", "正常角色"},
324				},
325				Resource: Resource{ID: "资" + invalidByte + "源", Scope: scope},
326				Action:   action,
327			},
328			Decision: Decision{
329				Allowed: true,
330				Reason:  "理" + invalidByte + "由",
331				Matched: []string{p2.ID, p1.ID}, // sorted by raw bytes
332				Version: 1,
333			},
334		}, prev)
335		prev = rec2.Fingerprint
336		rec3 := syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
337			Request: OrgRequest{
338				SubjectOrg:  org,
339				ResourceOrg: org,
340				Subject:     Subject{ID: "尾" + invalidByte + "随"},
341				Resource:    Resource{ID: "later", Scope: "org/a"},
342				Action:      "read",
343			},
344			Decision: Decision{Allowed: false, Reason: "no matching allow policy", Version: 1},
345		}, prev)
346		recs := []AuditRecord{rec1, rec2, rec3}
347		cp := Checkpoint{Org: org, EndSeq: 3, Fingerprint: rec3.Fingerprint}
348		if err := VerifyAudit(org, recs, cp); err != nil {
349			t.Fatalf("test fixture must verify: %v", err)
350		}
351		return org, recs, cp
352	}
353	
354	// TestTamperedInvalidBytesRejectedEverywhere replaces the lone 0xFF in
355	// every protected field with either 0xFE (the same display after JSON
356	// replacement) or a genuine U+FFFD. VerifyAudit must fail with
357	// ErrInvalidRange and offline review must refuse before returning any
358	// conclusion, including when the damage is after the target decision.
359	func TestTamperedInvalidBytesRejectedEverywhere(t *testing.T) {
360		org, good, cp := buildInvalidByteChain(t)
361	
362		// Document the root cause: JSON renders both raw bytes identically.
363		j1, _ := json.Marshal("身" + invalidByte + "份")
364		j2, _ := json.Marshal("身" + anotherInvalidByte + "份")
365		if !bytes.Equal(j1, j2) {
366			t.Fatalf("test premise broken: JSON differs: %s vs %s", j1, j2)
367		}
368	
369		mutators := []struct {
370			name string
371			fn   func([]AuditRecord, string)
372		}{
373			{"header org", func(r []AuditRecord, repl string) {
374				r[0].Org = strings.Replace(r[0].Org, invalidByte, repl, 1)
375			}},
376			{"record kind", func(r []AuditRecord, repl string) {
377				r[1].Kind += repl
378			}},
379			{"policy id", func(r []AuditRecord, repl string) {
380				p := &r[0].Change.Policies[0]
381				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
382			}},
383			{"policy subject", func(r []AuditRecord, repl string) {
384				p := &r[0].Change.Policies[0]
385				p.Subject = strings.Replace(p.Subject, invalidByte, repl, 1)
386			}},
387			{"policy action", func(r []AuditRecord, repl string) {
388				p := &r[0].Change.Policies[0]
389				p.Action = strings.Replace(p.Action, invalidByte, repl, 1)
390			}},
391			{"policy scope", func(r []AuditRecord, repl string) {
392				p := &r[0].Change.Policies[0]
393				p.Scope = strings.Replace(p.Scope, invalidByte, repl, 1)
394			}},
395			{"policy effect", func(r []AuditRecord, repl string) {
396				p := &r[0].Change.Policies[0]
397				p.Effect = Effect(string(p.Effect) + repl)
398			}},
399			{"second policy in list", func(r []AuditRecord, repl string) {
400				p := &r[0].Change.Policies[1]
401				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
402			}},
403			{"subject org", func(r []AuditRecord, repl string) {
404				r[1].Decision.Request.SubjectOrg = strings.Replace(r[1].Decision.Request.SubjectOrg, invalidByte, repl, 1)
405			}},
406			{"resource org", func(r []AuditRecord, repl string) {
407				r[1].Decision.Request.ResourceOrg = strings.Replace(r[1].Decision.Request.ResourceOrg, invalidByte, repl, 1)
408			}},
409			{"subject id between chinese", func(r []AuditRecord, repl string) {
410				id := &r[1].Decision.Request.Subject.ID
411				*id = strings.Replace(*id, invalidByte, repl, 1)
412			}},
413			{"subject kind", func(r []AuditRecord, repl string) {
414				r[1].Decision.Request.Subject.Kind = strings.Replace(r[1].Decision.Request.Subject.Kind, invalidByte, repl, 1)
415			}},
416			{"first role in list", func(r []AuditRecord, repl string) {
417				roles := r[1].Decision.Request.Subject.Roles
418				roles[0] = strings.Replace(roles[0], invalidByte, repl, 1)
419			}},
420			{"second role in list", func(r []AuditRecord, repl string) {
421				r[1].Decision.Request.Subject.Roles[1] += repl
422			}},
423			{"resource id", func(r []AuditRecord, repl string) {
424				r[1].Decision.Request.Resource.ID = strings.Replace(r[1].Decision.Request.Resource.ID, invalidByte, repl, 1)
425			}},
426			{"resource scope", func(r []AuditRecord, repl string) {
427				r[1].Decision.Request.Resource.Scope = strings.Replace(r[1].Decision.Request.Resource.Scope, invalidByte, repl, 1)
428			}},
429			{"request action", func(r []AuditRecord, repl string) {
430				r[1].Decision.Request.Action = strings.Replace(r[1].Decision.Request.Action, invalidByte, repl, 1)
431			}},
432			{"decision reason", func(r []AuditRecord, repl string) {
433				r[1].Decision.Decision.Reason = strings.Replace(r[1].Decision.Decision.Reason, invalidByte, repl, 1)
434			}},
435			{"first matched policy", func(r []AuditRecord, repl string) {
436				m := r[1].Decision.Decision.Matched
437				m[0] = strings.Replace(m[0], invalidByte, repl, 1)
438			}},
439			{"second matched policy", func(r []AuditRecord, repl string) {
440				m := r[1].Decision.Decision.Matched
441				m[1] = strings.Replace(m[1], invalidByte, repl, 1)
442			}},
443			{"record after target", func(r []AuditRecord, repl string) {
444				id := &r[2].Decision.Request.Subject.ID
445				*id = strings.Replace(*id, invalidByte, repl, 1)
446			}},
447		}
448	
449		for _, repl := range []string{anotherInvalidByte, replacementRune} {
450			for _, m := range mutators {
451				recs := cloneExportedRecords(good)
452				m.fn(recs, repl)
453				name := m.name + "/repl=" + replacementLabel(repl)
454				if err := VerifyAudit(org, recs, cp); !errors.Is(err, ErrInvalidRange) {
455					t.Fatalf("%s: VerifyAudit err = %v, want ErrInvalidRange", name, err)
456				}
457				// Offline review must reject first: never a successful or
458				// "consistent" conclusion over tampered material.
459				if got, err := RecheckDecisionOffline(org, recs, cp, 2); !errors.Is(err, ErrInvalidRange) {
460					t.Fatalf("%s: RecheckDecisionOffline err = %v, review = %+v, want ErrInvalidRange", name, err, got)
461				}
462			}
463		}
464	}
465	
466	// replacementLabel names a substitution without relying on rendered
467	// output, which displays both cases as a replacement character.
468	func replacementLabel(s string) string {
469		switch s {
470		case anotherInvalidByte:
471			return "0xFE"
472		case replacementRune:
473			return "U+FFFD"
474		default:
475			return "?"
476		}
477	}
478	
479	// TestReplacementRuneIsGenuineContentToo separates three byte-different
480	// strings that displays may conflate: a lone 0xFF, a lone 0xFE, and a
481	// real U+FFFD rune. A record genuinely containing U+FFFD is valid UTF-8,
482	// verifies and keeps the legacy fingerprint; substituting any one for
483	// another is a content change.
484	func TestReplacementRuneIsGenuineContentToo(t *testing.T) {
485		s := NewStore()
486		policies := []Policy{{
487			ID:      "p-" + replacementRune + "-1",
488			Subject: "用" + replacementRune + "戶",
489			Action:  "read", Scope: "org/a", Effect: EffectAllow,
490		}}
491		s.Publish("acme", 0, policies)
492		req := request("acme", "用"+replacementRune+"戶", "r1", "org/a", "read")
493		d := s.Decide("acme", req)
494		if !d.Allowed {
495			t.Fatalf("request with genuine U+FFFD = %+v", d)
496		}
497		recs, cp, err := s.AuditExport("acme", 0)
498		if err != nil {
499			t.Fatal(err)
500		}
501		if err := VerifyAudit("acme", recs, cp); err != nil {
502			t.Fatalf("genuine U+FFFD must verify: %v", err)
503		}
504		if !utf8.ValidString(recs[0].Change.Policies[0].ID) {
505			t.Fatal("genuine U+FFFD must remain valid UTF-8")
506		}
507		if fingerprintFor(&recs[0]) != legacyJSONFingerprint(&recs[0]) {
508			t.Fatal("valid-UTF-8 U+FFFD record must keep the legacy JSON fingerprint")
509		}
510		if review, err := RecheckDecisionOffline("acme", recs, cp, 2); err != nil || !review.Consistent {
511			t.Fatalf("genuine U+FFFD review = %+v, %v", review, err)
512		}
513	
514		// Raw invalid bytes exported from the live API.
515		raw := NewStore()
516		raw.Publish("acme", 0, []Policy{{
517			ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow,
518		}})
519		rawRecs, rawCP, err := raw.AuditExport("acme", 0)
520		if err != nil {
521			t.Fatal(err)
522		}
523		if err := VerifyAudit("acme", rawRecs, rawCP); err != nil {
524			t.Fatalf("raw-byte record must verify: %v", err)
525		}
526	
527		// Replace the raw byte with a genuine U+FFFD rune: content changed.
528		tampered := cloneExportedRecords(rawRecs)
529		tampered[0].Change.Policies[0].ID = "p" + replacementRune
530		if err := VerifyAudit("acme", tampered, rawCP); !errors.Is(err, ErrInvalidRange) {
531			t.Fatalf("raw 0xFF -> U+FFFD err = %v, want ErrInvalidRange", err)
532		}
533	
534		// The reverse substitution is also a change: the valid-UTF-8 record's
535		// real U+FFFD replaced by a lone 0xFF.
536		back := cloneExportedRecords(recs)
537		back[0].Change.Policies[0].ID = "p-" + invalidByte + "-1"
538		if err := VerifyAudit("acme", back, cp); !errors.Is(err, ErrInvalidRange) {
539			t.Fatalf("U+FFFD -> raw 0xFF err = %v, want ErrInvalidRange", err)
540		}
541	}
542	
543	// TestLegacyFingerprintsUnchangedForValidUTF8 proves byte-identical
544	// fingerprints for valid UTF-8 across policy changes, rollbacks,
545	// decisions, nil-vs-empty lists, and strings full of characters JSON
546	// escapes specially: Chinese, quotes, backslashes, control characters,
547	// angle/ampersand and a genuine replacement rune.
548	func TestLegacyFingerprintsUnchangedForValidUTF8(t *testing.T) {
549		org := "acme"
550		tricky := []Policy{{
551			ID:        "p\"1\\中\t\n\r<>&" + replacementRune,
552			Subject:   "主\"体\\",
553			Action:    "a\tb\nc",
554			Scope:     "org/中/区",
555			Effect:    EffectAllow,
556			Recursive: true,
557		}}
558		prev := genesisFingerprint(org)
559		records := []AuditRecord{
560			syntheticRecord(org, 1, AuditPolicyChange, &PolicyChange{
561				Version: 1, Policies: tricky,
562			}, nil, prev),
563		}
564		prev = records[0].Fingerprint
565		// Rollback carrying a nil policy set.
566		records = append(records, syntheticRecord(org, 2, AuditPolicyChange, &PolicyChange{
567			Version: 2, Policies: nil, SourceVersion: 1, RolledBack: true,
568		}, nil, prev))
569		prev = records[1].Fingerprint
570		// Decision with nil roles and nil matched lists.
571		records = append(records, syntheticRecord(org, 3, AuditDecision, nil, &DecisionRecord{
572			Request: OrgRequest{
573				SubjectOrg:  org,
574				ResourceOrg: org,
575				Subject:     Subject{ID: "身\"份\\中"},
576				Resource:    Resource{ID: "r\"1", Scope: "org/中/区"},
577				Action:      "a\tb",
578			},
579			Decision: Decision{Allowed: true, Reason: "理\"由\n中", Version: 2},
580		}, prev))
581		prev = records[2].Fingerprint
582		// Decision with explicitly empty (non-nil) lists.
583		records = append(records, syntheticRecord(org, 4, AuditDecision, nil, &DecisionRecord{
584			Request: OrgRequest{
585				SubjectOrg:  org,
586				ResourceOrg: org,
587				Subject:     Subject{ID: "u2", Roles: []string{}},
588				Resource:    Resource{ID: "r2", Scope: "org/a"},
589				Action:      "read",
590			},
591			Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: []string{}, Version: 2},
592		}, prev))
593	
594		for i := range records {
595			r := &records[i]
596			if got := fingerprintFor(r); got != legacyJSONFingerprint(r) {
597				t.Fatalf("record %d fingerprint drifted from the legacy JSON encoding", r.Seq)
598			}
599		}
600		cp := Checkpoint{Org: org, EndSeq: len(records), Fingerprint: records[len(records)-1].Fingerprint}
601		if err := VerifyAudit(org, records, cp); err != nil {
602			t.Fatalf("legacy-compatible chain must verify: %v", err)
603		}
604	
605		// Sanity: an invalid byte makes the same shape leave the JSON family.
606		raw := syntheticRecord(org, 5, AuditDecision, nil, &DecisionRecord{
607			Request:  request(org, "u"+invalidByte, "r1", "org/a", "read"),
608			Decision: Decision{Allowed: false, Reason: "x", Version: 2},
609		}, cp.Fingerprint)
610		if fingerprintFor(&raw) == legacyJSONFingerprint(&raw) {
611			t.Fatal("invalid-byte envelope unexpectedly shares the JSON fingerprint")
612		}
613	}
