186	// expectMarkerFailure reframes one mutated payload with a consistent outer
187	// length and checksum, then asserts the read fails with the wanted error
188	// class (and not the other one), delivers no records, and rewrites neither
189	// the archive bytes nor the retained checkpoint handed to it.
190	func expectMarkerFailure(t *testing.T, name string, payload []byte, cp Checkpoint, want, notWant error, wantSubstr string) {
191		t.Helper()
192		data := framePayload(payload)
193		dataSnapshot := append([]byte(nil), data...)
194		cpSnapshot := cp
195	
196		got, err := DecodeAuditArchive(data, "acme", cp)
197		if !errors.Is(err, want) {
198			t.Fatalf("%s: err = %v, want %v", name, err, want)
199		}
200		if errors.Is(err, notWant) {
201			t.Fatalf("%s: err = %v must not be %v", name, err, notWant)
202		}
203		if got != nil {
204			t.Fatalf("%s: returned %d records on a damaged marker, want nil", name, len(got))
205		}
206		if wantSubstr != "" && !strings.Contains(err.Error(), wantSubstr) {
207			t.Fatalf("%s: err = %q, want substring %q", name, err.Error(), wantSubstr)
208		}
209		if !bytes.Equal(data, dataSnapshot) {
210			t.Fatalf("%s: failed decode rewrote the archive bytes", name)
211		}
212		if cp != cpSnapshot {
213			t.Fatalf("%s: failed decode rewrote the retained checkpoint", name)
214		}
215	}
