217	// TestArchiveMarkerFixtureLayout locks the fixture's marker map: every
218	// marker kind appears, in both legal states, exactly where the walker
219	// expects it. A format or fixture change breaks this test instead of
220	// silently moving the corruption targets of the other tests in this file.
221	func TestArchiveMarkerFixtureLayout(t *testing.T) {
222		archive, _, _ := markerFixture(t)
223		events := walkMarkerPayload(t, payloadOf(t, archive))
224	
225		want := []struct {
226			name  string
227			value byte
228		}{
229			{"record 1 change payload", archiveTagPresent},
230			{"record 1 policy list", archiveTagPresent},
231			{"record 1 policy 0 recursive", archiveTagBoolTrue},
232			{"record 1 policy 1 recursive", archiveTagBoolFalse},
233			{"record 1 rolled back", archiveTagBoolFalse},
234			{"record 1 decision payload", archiveTagNil},
235			{"record 2 change payload", archiveTagNil},
236			{"record 2 decision payload", archiveTagPresent},
237			{"record 2 subject roles", archiveTagPresent},
238			{"record 2 subject disabled", archiveTagBoolFalse},
239			{"record 2 decision allowed", archiveTagBoolTrue},
240			{"record 2 matched policies", archiveTagPresent},
241			{"record 3 change payload", archiveTagPresent},
242			{"record 3 policy list", archiveTagPresent}, // non-nil empty set
243			{"record 3 rolled back", archiveTagBoolFalse},
244			{"record 3 decision payload", archiveTagNil},
245			{"record 4 change payload", archiveTagPresent},
246			{"record 4 policy list", archiveTagNil},
247			{"record 4 rolled back", archiveTagBoolFalse},
248			{"record 4 decision payload", archiveTagNil},
249			{"record 5 change payload", archiveTagPresent},
250			{"record 5 policy list", archiveTagPresent},
251			{"record 5 policy 0 recursive", archiveTagBoolTrue},
252			{"record 5 policy 1 recursive", archiveTagBoolFalse},
253			{"record 5 rolled back", archiveTagBoolTrue},
254			{"record 5 decision payload", archiveTagNil},
255			{"record 6 change payload", archiveTagNil},
256			{"record 6 decision payload", archiveTagPresent},
257			{"record 6 subject roles", archiveTagNil},
258			{"record 6 subject disabled", archiveTagBoolTrue},
259			{"record 6 decision allowed", archiveTagBoolFalse},
260			{"record 6 matched policies", archiveTagNil},
261		}
262		if len(events) != len(want) {
263			t.Fatalf("walked %d marker sites, want %d: %+v", len(events), len(want), events)
264		}
265		for i, w := range want {
266			if events[i].name != w.name || events[i].value != w.value {
267				t.Fatalf("marker %d = %+v, want %s with value %d", i, events[i], w.name, w.value)
268			}
269		}
270	}
