272	// TestArchiveInvalidMarkerBytesRejected corrupts every single-byte marker
273	// in turn to a value the format does not define (2 and 0xff). The outer
274	// length and checksum are recomputed, so they still validate: the
275	// rejection must come from the internal marker check, surface as
276	// ErrInvalidArchive (matched by errors.Is, and never as the content error
277	// ErrInvalidRange), and deliver no records — an arbitrary non-zero byte is
278	// not "true" and not "present".
279	func TestArchiveInvalidMarkerBytesRejected(t *testing.T) {
280		archive, _, cp := markerFixture(t)
281		basePayload := payloadOf(t, archive)
282		events := walkMarkerPayload(t, basePayload)
283	
284		for _, ev := range events {
285			for _, bad := range []byte{2, 0xff} {
286				payload := append([]byte(nil), basePayload...)
287				payload[ev.at] = bad
288				expectMarkerFailure(t, fmt.Sprintf("%s -> %d", ev.name, bad),
289					payload, cp, ErrInvalidArchive, ErrInvalidRange, "marker")
290			}
291		}
292	}
293	
294	// TestArchiveBooleanFlipChangesContentNotFormat flips every boolean marker
295	// between its two legal values. The archive stays structurally readable —
296	// every marker, length and count is intact — but the audited content no
297	// longer matches the original fingerprints, so against the caller's
298	// retained checkpoint the read must fail as ErrInvalidRange, never be
299	// reported as archive-format damage, and deliver no records.
300	func TestArchiveBooleanFlipChangesContentNotFormat(t *testing.T) {
301		archive, _, cp := markerFixture(t)
302		basePayload := payloadOf(t, archive)
303		events := walkMarkerPayload(t, basePayload)
304	
305		isBool := func(name string) bool {
306			return strings.Contains(name, "recursive") ||
307				strings.Contains(name, "rolled back") ||
308				strings.Contains(name, "disabled") ||
309				strings.Contains(name, "allowed")
310		}
311		flipped := 0
312		for _, ev := range events {
313			if !isBool(ev.name) {
314				continue
315			}
316			flipped++
317			payload := append([]byte(nil), basePayload...)
318			payload[ev.at] = ev.value ^ 1 // 0 becomes 1, 1 becomes 0: still a legal marker
319			expectMarkerFailure(t, ev.name+" flipped", payload, cp, ErrInvalidRange, ErrInvalidArchive, "")
320		}
321		if flipped != 12 {
322			t.Fatalf("flipped %d boolean sites, want the 12 the fixture carries", flipped)
323		}
324	}
325	
326	// TestArchiveLaterRecordMarkerDamageDiscardsPrefix is the all-or-nothing
327	// boundary: every record but the last decodes cleanly, yet one illegal
328	// marker in the final record fails the whole read. The intact prefix is
329	// proved readable on its own, so a nil result for the full archive can
330	// only mean the prefix was deliberately withheld.
331	func TestArchiveLaterRecordMarkerDamageDiscardsPrefix(t *testing.T) {
332		archive, recs, cp := markerFixture(t)
333		basePayload := payloadOf(t, archive)
334		events := walkMarkerPayload(t, basePayload)
335	
336		// The first five records, archived with their own checkpoint, read and
337		// review fine: the prefix really is intact.
338		prefixCP := Checkpoint{Org: "acme", EndSeq: 5, Fingerprint: recs[4].Fingerprint}
339		prefixArchive, err := EncodeAuditArchive("acme", recs[:5], prefixCP)
340		if err != nil {
341			t.Fatalf("encode prefix: %v", err)
342		}
343		prefix, err := DecodeAuditArchive(prefixArchive, "acme", prefixCP)
344		if err != nil || len(prefix) != 5 {
345			t.Fatalf("intact prefix must decode: %d records, %v", len(prefix), err)
346		}
347		if review, err := RecheckDecisionOffline("acme", prefix, prefixCP, 2); err != nil || !review.Consistent {
348			t.Fatalf("intact prefix must review: %+v, %v", review, err)
349		}
350	
351		// An illegal boolean marker and an illegal list marker in the last
352		// record each sink the entire read; no record prefix comes back.
353		for _, site := range []string{"record 6 decision allowed", "record 6 matched policies", "record 6 change payload"} {
354			payload := append([]byte(nil), basePayload...)
355			payload[markerOffset(t, events, site)] = 0xff
356			expectMarkerFailure(t, site, payload, cp, ErrInvalidArchive, ErrInvalidRange, "marker")
357		}
358	}
359	
360	// TestArchiveUndamagedMarkersRoundTrip is the control: the same fixture
361	// with no byte touched decodes cleanly, keeps every boolean's exact value
362	// and the nil versus non-nil-empty versus populated distinction of every
363	// list, and still feeds the existing offline decision review.
364	func TestArchiveUndamagedMarkersRoundTrip(t *testing.T) {
365		archive, recs, cp := markerFixture(t)
366		got, err := DecodeAuditArchive(archive, "acme", cp)
367		if err != nil {
368			t.Fatalf("decode control: %v", err)
369		}
370		if !reflect.DeepEqual(got, recs) {
371			t.Fatalf("control round trip changed the records:\n got %+v\nwant %+v", got, recs)
372		}
373	
374		// Booleans keep their exact values in both states.
375		if !got[0].Change.Policies[0].Recursive || got[0].Change.Policies[1].Recursive {
376			t.Fatal("policy Recursive booleans changed across the archive")
377		}
378		if got[0].Change.RolledBack || !got[4].Change.RolledBack {
379			t.Fatal("RolledBack booleans changed across the archive")
380		}
381		if got[1].Decision.Request.Subject.Disabled || !got[5].Decision.Request.Subject.Disabled {
382			t.Fatal("subject Disabled booleans changed across the archive")
383		}
384		if !got[1].Decision.Decision.Allowed || got[5].Decision.Decision.Allowed {
385			t.Fatal("decision Allowed booleans changed across the archive")
386		}
387	
388		// Nil, non-nil empty and populated lists keep their distinct shapes.
389		if got[2].Change.Policies == nil || len(got[2].Change.Policies) != 0 {
390			t.Fatal("non-nil empty policy set lost its shape")
391		}
392		if got[3].Change.Policies != nil {
393			t.Fatal("nil policy set decoded as non-nil")
394		}
395		if got[5].Decision.Request.Subject.Roles != nil || got[5].Decision.Decision.Matched != nil {
396			t.Fatal("nil roles/matched lists decoded as non-nil")
397		}
398		if want := []string{"role-a", "role-b"}; !reflect.DeepEqual(got[1].Decision.Request.Subject.Roles, want) {
399			t.Fatalf("roles = %q, want %q", got[1].Decision.Request.Subject.Roles, want)
400		}
401		if want := []string{"p1", "p2"}; !reflect.DeepEqual(got[1].Decision.Decision.Matched, want) {
402			t.Fatalf("matched = %q, want %q", got[1].Decision.Decision.Matched, want)
403		}
404	
405		// The decoded material still serves the existing offline review, for
406		// the allowed decision and for the disabled-subject denial alike.
407		allowReview, err := RecheckDecisionOffline("acme", got, cp, 2)
408		if err != nil || !allowReview.Consistent || !allowReview.Recomputed.Allowed {
409			t.Fatalf("control allow review = %+v, %v", allowReview, err)
410		}
411		denyReview, err := RecheckDecisionOffline("acme", got, cp, 6)
412		if err != nil || !denyReview.Consistent || denyReview.Recomputed.Allowed {
413			t.Fatalf("control disabled-subject review = %+v, %v", denyReview, err)
414		}
415	}
