package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
	"runtime"
	"strings"
	"testing"
)

func scratchLocateReasonLen(payload []byte, reason string) int {
	idx := bytes.Index(payload, []byte(reason))
	if idx < 0 {
		panic("reason not found")
	}
	return idx - 4
}

func scratchFrame(payload []byte) []byte {
	out := append([]byte(nil), archiveMagic...)
	var lb [4]byte
	binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
	out = append(out, lb[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	return append(out, sum[:]...)
}

func TestScratchReasonLength(t *testing.T) {
